/* GRIDLINE Studio — self-contained progressive web UI, no network dependencies. */
const A={user:null,templates:[],themes:{},games:[],draft:null,editorRound:0,modal:null,editingQuestion:null,session:null,liveCode:null,liveRole:null,es:null,player:null,custom:null,saveTimer:null,saveFlag:'',prefs:{},menu:false,race:localStorage.getItem('gridline:race')==='1',stageMode:'full',lastRoute:'',working:false,health:null};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>{if(typeof crypto!=='undefined'&&typeof crypto.randomUUID==='function')return crypto.randomUUID();const x=new Uint8Array(16);if(typeof crypto!=='undefined'&&crypto.getRandomValues)crypto.getRandomValues(x);else for(let i=0;i<16;i++)x[i]=Math.floor(Math.random()*256);x[6]=(x[6]&15)|64;x[8]=(x[8]&63)|128;const h=[...x].map(n=>n.toString(16).padStart(2,'0')).join('');return `${h.slice(0,8)}-${h.slice(8,12)}-${h.slice(12,16)}-${h.slice(16,20)}-${h.slice(20)}`;};
const ICON={arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',play:'<path d="m8 5 11 7-11 7z"/>',edit:'<path d="m15 5 4 4M4 20h4l12-12a2.8 2.8 0 0 0-4-4L4 16v4z"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>',trash:'<path d="M4 7h16m-10 4v6m4-6v6M6 7l1 14h10l1-14M9 7V4h6v3"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',users:'<path d="M16 20v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8M23 20v-2a4 4 0 0 0-3-3.87M16 2.13a4 4 0 0 1 0 7.75"/>',check:'<path d="M4 12l5 5L20 6"/>',x:'<path d="M5 5l14 14M19 5 5 19"/>',back:'<path d="M19 12H5m6 6-6-6 6-6"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 8a7 7 0 0 1 12-1l2 5M4 12l2 5a7 7 0 0 0 12-1"/>',tune:'<path d="M4 7h16M4 17h16M9 4v6M16 14v6"/>',bolt:'<path d="M13 2 5 13h7l-1 9 8-11h-7z"/>',log:'<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9"/>',sound:'<path d="M4 9v6h4l5 4V5L8 9H4m12 0a5 5 0 0 1 0 6"/>',link:'<path d="M10 13a5 5 0 0 0 7 .3l3-3a5 5 0 0 0-7-7l-1.7 1.7M14 11a5 5 0 0 0-7-.3l-3 3a5 5 0 0 0 7 7l1.7-1.7"/>',chev:'<path d="m9 18 6-6-6-6"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-10h.01"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>'};
const ico=(name)=>`<span class="icon" aria-hidden="true"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24">${ICON[name]||ICON.bolt}</svg></span>`;
const logo=()=>`<a class="brand" href="/" data-link aria-label="GRIDLINE home"><svg class="brand-mark" viewBox="0 0 46 46" aria-hidden="true"><path fill="var(--accent)" d="M6 5H40V13H14V33H33V26H25V19H41V41H6Z"/></svg> GRIDLINE<strong>.</strong></a>`;
const btn=(text,action,variant='ghost',icon='',attrs='')=>`<button class="btn ${variant}" data-action="${action}" ${attrs}>${icon?ico(icon):''}${text}</button>`;
const titleBlock=(pre,title,desc='')=>`<div><div class="eyebrow">${pre}</div><h1 class="display h1">${title}</h1>${desc?`<p class="muted">${desc}</p>`:''}</div>`;
const openRoute=()=>location.pathname;
const codeFromRoute=()=>openRoute().match(/^\/(?:session|join)\/([A-Z0-9]{6})/i)?.[1].toUpperCase();
function toast(message,bad=false){const e=document.createElement('div');e.className='toast-item'+(bad?' error':'');e.textContent=message;$('#toast').append(e);setTimeout(()=>{e.remove();},4500);}
async function api(path,{method='GET',body,headers={}}={}){
 const h={'Accept':'application/json',...headers};if(body!==undefined)h['Content-Type']='application/json';
 if(!['GET','HEAD'].includes(method)&&A.user?.csrf)h['x-gridline-csrf']=A.user.csrf;
 const code=path.match(/^\/api\/sessions\/([A-Z0-9]{6})/i)?.[1]?.toUpperCase();
 if(code){const demo=localStorage.getItem(`gridline:demo:${code}`),p=localStorage.getItem(`gridline:player:${code}`);if(demo)h['x-demo-host-token']=demo;if(p&&(['buzz','wager','answer','heartbeat'].some(t=>path.endsWith('/'+t)))){try{h['x-player-token']=JSON.parse(p).token;}catch{}}}
 const response=await fetch(path,{method,headers:h,credentials:'same-origin',body:body!==undefined?JSON.stringify(body):undefined});
 let data;try{data=await response.json();}catch{throw new Error('Server returned an invalid response');}
 if(!response.ok)throw new Error(data?.error||`Request failed: ${response.status}`);return data;
}
const download=(name,data,type='application/json')=>{const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);};
function applyTheme(nameOrColors){let t=typeof nameOrColors==='string'?A.themes[nameOrColors]:nameOrColors;if(!t)t=A.themes.papaya;if(!t)return;for(const k of ['bg','elev','card','border','text','muted','accent','accent2','board','tile','good','bad'])if(t[k]&&/^#[0-9a-f]{6}$/i.test(t[k]))document.documentElement.style.setProperty('--'+k,t[k]);document.querySelector('meta[name="theme-color"]')?.setAttribute('content',t.bg);document.documentElement.style.colorScheme=t.bg==='#F2F4F6'?'light':'dark';}
function routeTheme(){if(A.session&&codeFromRoute()){applyTheme(A.session.theme);}else if(A.custom){applyTheme(A.custom);}else{applyTheme(localStorage.getItem('gridline:theme')||'papaya');}}
function header(){const path=openRoute(),active=p=>path.startsWith(p)?'active':'';return `<header class="topbar"><div class="shell nav-inner">${logo()}<nav class="nav-links" aria-label="Primary navigation"><a href="/studio" data-link class="${active('/studio')}">THE STUDIO</a><a href="/templates" data-link class="${active('/templates')}">TEMPLATES</a><a href="/themes" data-link class="${active('/themes')}">THEME LAB</a><a href="/help" data-link class="${active('/help')}">HOW IT WORKS</a></nav><div class="nav-actions">${btn('JOIN GAME','join-go','ghost','users')}${A.user?`<button class="btn primary" data-nav="/studio">${ico('bolt')} ${esc(A.user.username)}</button>`:btn('LAUNCH STUDIO','studio-go','primary','arrow')}<button class="btn icon-only nav-menu" data-action="menu" aria-label="Toggle navigation">${ico('menu')}</button></div></div>${A.menu?`<nav class="mobile-panel" aria-label="Mobile navigation"><a href="/studio" data-link>STUDIO</a><a href="/templates" data-link>TEMPLATES</a><a href="/themes" data-link>THEME LAB</a><a href="/help" data-link>HOW IT WORKS</a></nav>`:''}</header>`;}
const footer=()=>`<footer class="shell footer"><div>© GRIDLINE STUDIO • ORIGINAL INTERACTIVE ENTERTAINMENT</div><div>EVERY ANSWER CHANGES THE GAME. &nbsp; / &nbsp; v0.8.0</div></footer>`;
function home(){const cats=['WORLD','SCIENCE','CINEMA','SPORT','HISTORY'], tiles=[200,400,600,800];return `<section class="hero"><div class="shell hero-inner"><div class="hero-copy"><div class="eyebrow">WELCOME TO THE NEW ERA OF GAME NIGHT</div><h1 class="display title" style="margin-top:25px">THE<br>STAGE<br>IS <span class="accent">YOURS.</span></h1><p class="hero-sub">Create remarkable quiz nights. Command every round. Make every answer feel like a moment. This isn't another quiz app. It's your own show.</p><div class="btn-row">${btn('LAUNCH YOUR GAME','studio-go','primary','arrow')}${btn('ENTER LIVE DEMO','demo','ghost','play')}</div><div class="hero-idx"><b>01 / 04</b><span>DESIGN YOUR GAME<br>CONTROL THE MOMENT</span></div></div><div class="hero-preview"><div class="preview-head"><div class="flex"><span class="dot green"></span><span class="mono caps" style="font-size:10px">LIVE EVENT / GRIDLINE PREVIEW</span></div><span class="pill">ROUND 01</span></div><div class="preview-board"><div class="preview-grid">${cats.map(c=>`<div class="preview-cat">${c}</div>`).join('')}${tiles.flatMap(v=>cats.map((c,i)=>`<button class="preview-tile" data-action="demo" aria-label="Start demo for ${c} ${v}">${v}</button>`)).join('')}</div></div><div class="float-chip"><div class="statline">THE BOARD IS YOURS</div><b>6 × 5 <span class="accent">.</span></b></div></div></div></section><section class="ribbon"><div class="shell ribbon-row"><span>HOST-CONTROLLED GAMEPLAY</span><span>REAL-TIME BUZZERS</span><span>TRUE MULTIPLAYER</span><span>ANY SCREEN. ANYWHERE.</span></div></section><section class="section shell showcase"><div><div class="eyebrow">DESIGNED FOR THE MOMENT</div><h2 class="display h2" style="margin:18px 0 24px">YOUR OWN<br><span class="accent">RACE CONTROL.</span></h2><p class="muted" style="max-width:430px;font-size:16px;line-height:1.8">Imagine the precision of a race control room, designed for trivia. Refined interfaces. Fast decisions. Zero wasted movement.</p><div class="feature-line"><b>01.</b><span>One powerful host command center</span></div><div class="feature-line"><b>02.</b><span>Real players. Real buzzers. Live scores.</span></div><div class="feature-line"><b>03.</b><span>Every detail, tuned to your show.</span></div>${btn('EXPLORE THE STUDIO','studio-go','primary','arrow')}</div><div class="showcase-panel"><div class="showcase-console"><div class="spread"><span class="eyebrow">RACE CONTROL</span><span class="pill"><span class="dot green"></span> SYSTEM LIVE</span></div><div style="padding:22px 0"><div class="statline">QUESTION ACTIVE</div><div class="clock">00:24<span class="accent">.</span></div></div><div class="console-lines"></div><div class="spread"><span class="mono">BUZZER STATUS</span><span class="pill">ARMED</span></div><div class="grid2" style="margin-top:20px">${btn('REVEAL','demo','ghost','play')}${btn('AWARD POINTS','demo','primary','check')}</div></div></div></section><section class="closing"><div class="shell"><div class="eyebrow">THE NEXT LEVEL OF GAME NIGHT</div><h2 class="display" style="margin:20px 0 32px">MAKE THE NEXT GAME <span class="accent">UNFORGETTABLE.</span></h2><div class="btn-row">${btn('CREATE YOUR FIRST GAME','studio-go','primary','arrow')}${btn('TRY THE LIVE DEMO','demo','ghost','play')}</div></div></section>`;}
function account(){return `<div class="shell pad-y"><div class="grid2" style="align-items:center;gap:55px"><div>${titleBlock('CONTROL STARTS HERE','YOUR STUDIO. YOUR RULES.','Create an account to save quizzes, manage live games and build your own game-show library.')}<div class="feature-line"><b>01.</b><span>Local-first. No paid APIs.</span></div><div class="feature-line"><b>02.</b><span>All game definitions saved in SQLite.</span></div><div class="feature-line"><b>03.</b><span>Players join without accounts.</span></div></div><div class="panel">${authForm('register')}</div></div></div>`;}
function authForm(mode){return `<form data-form="${mode}" class="stack"><div class="eyebrow">${mode==='register'?'FIRST-TIME HOST / REGISTER':'WELCOME BACK / SIGN IN'}</div><h2 class="display h3">${mode==='register'?'CREATE YOUR ACCOUNT':'RETURN TO CONTROL'}</h2><div class="field"><label for="auth-name">USERNAME</label><input id="auth-name" name="username" placeholder="Your studio ID" autocomplete="username" required minlength="3" maxlength="32" pattern="[a-zA-Z0-9_-]+"/></div><div class="field"><label for="auth-pass">PASSWORD</label><input id="auth-pass" type="password" name="password" placeholder="${mode==='register'?'At least 10 characters':'Your password'}" autocomplete="${mode==='register'?'new-password':'current-password'}" required minlength="${mode==='register'?'10':'1'}"/></div><button class="btn primary wide" type="submit">${mode==='register'?'CREATE STUDIO ACCOUNT':'SIGN IN'} ${ico('arrow')}</button><button type="button" class="btn ghost wide" data-action="auth-toggle">${mode==='register'?'ALREADY HAVE AN ACCOUNT? SIGN IN':'NEW HOST? CREATE AN ACCOUNT'}</button></form>`;}
function studio(){if(!A.user)return account();const games=A.games||[];return `<main class="shell pad-y" style="padding-top:0"><div class="page-head">${titleBlock('GOOD TO HAVE YOU BACK','CONTROL CENTER.','Build your next game. Continue an existing show. Take the stage.') }<div class="btn-row">${btn('IMPORT QUIZ','import-game','ghost','download')}${btn('NEW GAME','create-blank','primary','plus')}</div></div><div class="grid3" style="margin-bottom:29px"><div class="panel"><div class="statline">YOUR QUIZZES</div><div class="clock mini" style="margin-top:10px">${games.length.toString().padStart(2,'0')}</div><div class="smallprint">AVAILABLE IN YOUR LIBRARY</div></div><div class="panel"><div class="statline">TOTAL CATEGORIES</div><div class="clock mini" style="margin-top:10px">${games.reduce((s,g)=>s+g.rounds.reduce((k,r)=>k+r.categories.length,0),0).toString().padStart(2,'0')}</div><div class="smallprint">READY TO EDIT</div></div><div class="panel"><div class="statline">FAST ACTION</div><div style="margin-top:16px">${btn('LAUNCH A DEMO','demo','primary','play')}</div><div class="smallprint" style="margin-top:11px">FULLY INTERACTIVE SAMPLE</div></div></div><div class="section-heading"><div><div class="eyebrow">SAVED EXPERIENCES</div><h2 class="display h3" style="margin:12px 0 0">YOUR GAME LIBRARY</h2></div><div class="searchbar">${ico('info')}<input id="library-search" aria-label="Search saved quizzes" placeholder="Search games..." data-action-input="filter-games"/></div></div><div class="grid3" id="game-cards">${games.length?games.map(gameCard).join(''):`<div class="empty-state">NO GAMES YET. ${btn('CREATE A GAME','create-blank','primary','plus')}</div>`}</div><div class="spread" style="margin-top:45px"><div><span class="eyebrow">READY-MADE FOUNDATIONS</span><h2 class="display h3" style="margin:10px 0">START FROM A TEMPLATE.</h2></div>${btn('EXPLORE TEMPLATES','templates-go','ghost','arrow')}</div></main>`;}
function gameCard(g){const q=g.rounds.reduce((s,r)=>s+r.categories.reduce((t,c)=>t+c.questions.length,0),0),theme=A.themes[g.settings?.theme]||A.themes.papaya;return `<article class="game-card" data-search-title="${esc(g.title.toLowerCase()+' '+g.description.toLowerCase())}"><div class="game-art" style="--accent:${esc(theme.accent)};--board:${esc(theme.board)}"><span class="pill">${g.rounds.length} ROUND${g.rounds.length>1?'S':''}</span><b>GRID</b></div><div class="game-card-body"><h3>${esc(g.title)}</h3><p>${esc(g.description)}</p><div class="game-meta"><span>${q} QUESTIONS</span><span>EDITED ${new Date(g.updatedAt).toLocaleDateString()}</span></div><div class="btn-row"><button class="btn primary" data-action="launch" data-id="${g.id}">${ico('play')} LAUNCH</button><button class="btn ghost" data-nav="/game/${g.id}/edit">${ico('edit')} EDIT</button><button class="btn small ghost" data-action="clone" data-id="${g.id}" aria-label="Duplicate ${esc(g.title)}">${ico('copy')}</button><button class="btn small danger" data-action="delete-game" data-id="${g.id}" aria-label="Delete ${esc(g.title)}">${ico('trash')}</button></div></div></article>`;}
function templateGallery(){return `<div class="shell pad-y" style="padding-top:0"><div class="page-head">${titleBlock('BUILT TO GET YOU MOVING','THE STARTING GRID.','Curated, editable quiz boards with real sample questions. Everything is yours to customize.')}<div>${btn('BACK TO STUDIO','studio-go','ghost','back')}</div></div><div class="grid3">${A.templates.map(t=>{const th=A.themes[t.theme]||A.themes.papaya;return `<article class="game-card"><div class="game-art" style="--accent:${th.accent};--board:${th.board}"><span class="pill">${esc(t.difficulty)}</span><b>${esc(t.title.split(' ')[0])}</b></div><div class="game-card-body"><h3>${esc(t.title)}</h3><p>${esc(t.subtitle)}</p><div class="game-meta"><span>${t.game.rounds[0].categories.length} CATEGORIES</span><span>${t.game.rounds[0].categories.reduce((a,c)=>a+c.questions.length,0)} QUESTIONS</span></div><button class="btn primary wide" data-action="use-template" data-id="${t.id}">${ico('plus')} USE THIS TEMPLATE</button></div></article>`}).join('')}</div></div>`;}
function questionById(game,id){for(const [ri,r] of game.rounds.entries())for(const [ci,c] of r.categories.entries())for(const [qi,q] of c.questions.entries())if(q.id===id)return {ri,ci,qi,q,c,r};return null;}
function editor(){const g=A.draft;if(!g)return `<main class="shell pad-y">Loading quiz editor...</main>`;const r=g.rounds[A.editorRound]||g.rounds[0];const cats=r.categories;return `<div class="shell" style="padding-bottom:80px"><div class="page-head"><div><div class="eyebrow">THE QUIZ BUILDER / ${esc(g.title)}</div><h1 class="display h2" style="margin:12px 0">BUILD YOUR <span class="accent">GRID.</span></h1><span class="save-status" id="save-status">${esc(A.saveFlag||'ALL CHANGES SAVED')}</span></div><div class="btn-row">${btn('SAVE GAME','save-game','ghost','check')}${btn('LAUNCH GAME','launch','primary','play',`data-id="${g.id}"`)}</div></div><div class="editor-layout"><div class="editor-main stack"><div class="panel"><div class="panel-header"><h3>01 / EDIT YOUR BOARD</h3><span class="pill">${cats.length} CATEGORIES</span></div><div class="spread" style="flex-wrap:wrap"><div class="round-tab">${g.rounds.map((ro,i)=>`<button class="btn small ${i===A.editorRound?'active':'ghost'}" data-action="edit-round" data-index="${i}">${esc(ro.title||`ROUND ${i+1}`)}</button>`).join('')}</div>${btn('NEW ROUND','add-round','ghost','plus')}</div><div class="editor-tools" style="margin:17px 0"><button class="btn small ghost" data-action="add-category">${ico('plus')} ADD CATEGORY</button><button class="btn small ghost" data-action="rename-round">${ico('edit')} RENAME ROUND</button></div><div class="board-scroll"><div class="editor-grid" style="--cols:${cats.length}">${cats.map(c=>`<div class="editor-cat"><input aria-label="Category name" value="${esc(c.name)}" data-cat-name="${c.id}" maxlength="64"><div class="spread"><button class="btn tiny ghost" data-action="shift-category" data-id="${c.id}" data-dir="-1" title="Move left">←</button><button class="btn tiny ghost" data-action="duplicate-category" data-id="${c.id}" title="Duplicate">${ico('copy')}</button><button class="btn tiny danger" data-action="remove-category" data-id="${c.id}" title="Delete category">${ico('x')}</button><button class="btn tiny ghost" data-action="shift-category" data-id="${c.id}" data-dir="1" title="Move right">→</button></div></div>`).join('')}${Array.from({length:Math.max(...cats.map(c=>c.questions.length),0)},(_,qi)=>cats.map(c=>{let q=c.questions[qi];return q?`<button class="editor-tile ${q.prompt&&q.answer?'':'is-empty'}" data-action="edit-question" data-id="${q.id}">${q.value}<span>${esc(q.prompt||'ADD QUESTION TEXT')}</span></button>`:`<button class="editor-tile is-empty" data-action="add-question" data-id="${c.id}">+<span>NEW CLUE</span></button>`}).join('')).join('')}</div></div><p class="smallprint">Select any value to edit its question. Use the category arrows to reorder without dragging. Empty clues must be completed before they can be played.</p></div><div class="panel"><div class="panel-header"><h3>02 / THE FINAL ROUND</h3><span class="pill">OPTIONAL</span></div><div class="form-row"><div class="field"><label>FINAL CATEGORY</label><input data-final="category" value="${esc(g.final.category)}" maxlength="64"/></div><div class="field"><label>TIME LIMIT (SECONDS)</label><input type="number" min="5" max="3600" data-final="timeLimit" value="${g.final.timeLimit||45}"/></div></div><div class="field" style="margin-top:12px"><label>FINAL QUESTION</label><textarea data-final="question">${esc(g.final.question||'')}</textarea></div><div class="field" style="margin-top:12px"><label>CORRECT ANSWER</label><input data-final="answer" value="${esc(g.final.answer||'')}"/></div></div></div><aside class="editor-side stack"><div class="panel"><div class="panel-header"><h3>GAME IDENTITY</h3></div><div class="stack"><div class="field"><label>GAME TITLE</label><input data-game-field="title" value="${esc(g.title)}" maxlength="100"/></div><div class="field"><label>DESCRIPTION</label><textarea data-game-field="description">${esc(g.description)}</textarea></div><div class="field"><label>THEME</label><select data-game-setting="theme">${Object.entries(A.themes).map(([k,t])=>`<option value="${k}" ${g.settings.theme===k?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div></div></div><div class="panel"><div class="panel-header"><h3>GAMEPLAY RULES</h3></div><div class="side-list"><div class="setting"><label>DEFAULT TIMER</label><input type="number" min="5" max="3600" data-game-setting="timeLimit" value="${g.settings.timeLimit||30}"/></div><div class="setting"><label>WRONG ANSWER PENALTY</label><input type="checkbox" data-game-setting="negativePoints" ${g.settings.negativePoints?'checked':''}/></div><div class="setting"><label>AUTO-OPEN BUZZER</label><input type="checkbox" data-game-setting="buzzerMode" ${g.settings.buzzerMode==='auto'?'checked':''}/></div><div class="setting"><label>ENABLE FINAL ROUND</label><input type="checkbox" data-game-setting="finalEnabled" ${g.settings.finalEnabled?'checked':''}/></div><div class="setting"><label>ALLOW LATE JOINING</label><input type="checkbox" data-game-setting="allowLateJoin" ${g.settings.allowLateJoin!==false?'checked':''}/></div><div class="setting"><label>ENABLE SOUND</label><input type="checkbox" data-game-setting="sound" ${g.settings.sound?'checked':''}/></div></div></div><div class="panel"><div class="panel-header"><h3>TEAM DEFAULTS</h3></div><div class="stack">${g.settings.teams.map(t=>`<div class="field"><label><span class="color-team" style="background:${esc(t.color)}"></span>TEAM NAME</label><div class="flex"><input data-team-field="${t.id}" value="${esc(t.name)}" maxlength="32"/><button class="btn small danger" data-action="remove-default-team" data-id="${t.id}" title="Remove team" aria-label="Remove ${esc(t.name)}">${ico('x')}</button></div></div>`).join('')}${btn('ADD TEAM','add-default-team','ghost','plus')}</div></div><div class="panel"><div class="panel-header"><h3>DATA & CONTROL</h3></div><div class="stack">${btn('EXPORT THIS GAME','export-game','ghost','download',`data-id="${g.id}"`)}${btn('EXPORT QUESTION CSV','export-questions','ghost','download')}${btn('ADD 1 QUESTION PER CATEGORY','add-row','ghost','plus')}${g.rounds.length>1?btn('DELETE CURRENT ROUND','remove-round','danger','trash'):''}${btn('BACK TO LIBRARY','studio-go','ghost','back')}</div></div></aside></div></div>`;}
function boardGrid(s,interactive=false){const cat=s.categories||[];const cols=cat.length;return `<div class="board"><div class="board-grid" style="--cols:${cols}">${cat.map(c=>`<div class="board-heading">${esc(c.name)}</div>`).join('')}${Array.from({length:Math.max(0,...cat.map(c=>c.questions.length))},(_,r)=>cat.map(c=>{const q=c.questions[r];return q?`<button class="board-tile ${q.available?'':'used'}" ${interactive&&s.phase==='board'&&q.available?'':'disabled'} ${interactive?`data-action="select-live" data-id="${q.id}"`:''} aria-label="${esc(c.name)} for ${q.value} points">${q.available?q.value:'—'}</button>`:`<div class="board-tile used"></div>`}).join('')).join('')}</div></div>`;}
function clockHtml(s,mini=false){return `<div class="clock ${mini?'mini':''}" data-clock>${formatClock(s.timer)}</div><div class="clock-track"><div class="clock-track-fill" data-clock-track></div></div>`;}
function formatClock(t,serverTime=Date.now()){if(!t)return '00:00';const remaining=t.running?Math.max(0,Math.ceil((t.deadline-serverTime)/1000)):Math.max(0,Number(t.remaining)||0);return `${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;}
function teamBoard(s,full=false){return `<div class="scoreboard">${s.standings.map(t=>`<div class="team-score ${s.buzzerWinner&&s.players.find(p=>p.id===s.buzzerWinner)?.teamId===t.id?'active':''}" style="--team-color:${esc(t.color||'#FF8000')}"><div><div class="team-name">${esc(t.name)}</div><div class="team-members">${t.rank===1?'P'+t.rank+' / LEADER':'P'+t.rank} &nbsp; • &nbsp; ${s.players.filter(p=>p.teamId===t.id).length} PLAYERS</div></div><div class="score-number">${t.score}</div></div>`).join('')}</div>`;}
function selectedQuestion(s,stage=false){let q=s.question;return `<div class="question-display"><div class="cat-name">${esc(s.roundTitle||'ROUND')}&nbsp; / &nbsp; ${q?.value||0} POINTS</div><div class="question-value">${q?.value||0} <span class="accent">PTS</span></div><h2>${esc(q?.prompt||'Waiting for the next clue...')}</h2>${q?.imageUrl?`<img src="${esc(q.imageUrl)}" alt="Question illustration" loading="lazy">`:''}<span class="pill"><span class="dot ${s.buzzerOpen?'green':''}"></span>${s.buzzerWinner?'PLAYER LOCKED IN':s.buzzerOpen?'BUZZING IS OPEN':s.answerRevealed?'ANSWER REVEALED':'BUZZING CLOSED'}</span>${s.buzzerWinner?`<p class="caps" style="font-weight:900;color:var(--accent)">${esc(s.players.find(p=>p.id===s.buzzerWinner)?.name||'PLAYER')} BUZZED FIRST</p>`:''}${(stage&&s.answerRevealed)?`<div class="answer-key"><strong>CORRECT ANSWER</strong><span>${esc(q?.answer||'')}</span></div>`:''}</div>`;}
function lobby(s){return `<div class="lobby-hero"><div class="eyebrow">THE STAGE IS SET</div><h2>${esc(s.code)}</h2><p>Join with this code or go to <strong>${esc(location.host)}/join/${esc(s.code)}</strong></p><div class="btn-row" style="justify-content:center;margin:20px 0">${btn('COPY JOIN LINK','copy-join','primary','copy')}${btn('OPEN PLAYER VIEW','open-player','ghost','link')}</div><div class="people-wrap" style="justify-content:center;margin-top:23px">${s.players.length?s.players.map(p=>`<div class="player-chip"><span class="dot ${p.online?'green':'red'}"></span><b>${esc(p.name)}</b><small>${esc(s.teams.find(t=>t.id===p.teamId)?.name||'')}</small></div>`).join(''):`<span class="pill">WAITING FOR PLAYERS TO JOIN</span>`}</div></div>`;}
function activityList(s){return `<div class="activity">${(s.activity||[]).slice(0,9).map(a=>`<div class="activity-item"><span>${esc(new Date(a.at).toLocaleTimeString())}</span><b>${esc(a.detail)}</b></div>`).join('')||'<div class="smallprint">No events yet.</div>'}</div>`;}
function hostSession(){const s=A.session;if(!s)return `<div class="shell pad-y">Loading host session...</div>`;const isQuestion=s.phase==='question';const isFinal=s.phase.startsWith('final'), done=s.usedCount===s.totalCount;const winName=s.players.find(p=>p.id===s.buzzerWinner);const winTeam=winName?.teamId||s.teams[0]?.id;return `<div class="shell" style="padding-bottom:75px"><div class="session-bar"><div><div class="eyebrow">${s.phase==='results'?'RACE COMPLETED':'LIVE PRODUCTION / HOST STUDIO'}</div><h1 class="display h3" style="margin:10px 0">${esc(s.gameTitle)}</h1><span class="smallprint">SESSION <span class="session-code" style="font-size:15px">${esc(s.code)}</span> &nbsp; ${s.players.length} PARTICIPANTS</span></div><div class="btn-row">${btn(A.race?'STUDIO MODE':'RACE CONTROL','race-toggle','ghost','tune')}${btn('PRESENTATION','open-stage','ghost','expand')}${btn('COPY JOIN LINK','copy-join','primary','copy')}</div></div><div class="statusbar"><span><span class="dot green"></span> SERVER CONNECTED</span><span>${esc(s.phase.toUpperCase().replaceAll('-',' '))}</span><span>${esc(s.roundTitle||'FINAL ROUND')}</span><span>BOARD ${s.usedCount}/${s.totalCount}</span><span>REV ${s.revision}</span></div><div class="session-grid"><div class="session-main stack">${s.phase==='lobby'?lobby(s):s.phase==='board'?boardGrid(s,true):isQuestion?selectedQuestion(s,false):isFinal?finalDisplay(s,true):resultsDisplay(s,true)}${isQuestion?`<div class="panel"><div class="eyebrow">HOST-ONLY ANSWER KEY</div><div class="answer-key"><strong>CORRECT ANSWER / DO NOT SCREENSHARE THIS PANEL</strong><span>${esc(s.question?.answer||'')}</span>${s.question?.explanation?`<p>${esc(s.question.explanation)}</p>`:''}</div></div>`:''}<div class="panel"><div class="panel-header"><h3>SESSION ACTIVITY</h3><span class="pill">AUDIT LOG</span></div>${activityList(s)}</div></div><aside class="session-side"><div class="panel dark"><div class="panel-header"><h3>${A.race?'TELEMETRY / TEAMS':'LIVE LEADERBOARD'}</h3><span class="pill">${s.teams.length} TEAMS</span></div>${teamBoard(s)}<div class="btn-row" style="margin-top:13px">${btn('+ / − ADJUST','adjust-score','ghost','tune')}${btn('UNDO SCORE','undo-score','ghost','back')}</div></div>${s.phase!=='results'?`<div class="panel"><div class="panel-header"><h3>COMMAND CENTER</h3><span class="pill">HOST ONLY</span></div>${hostControls(s)}</div>`:''}${isQuestion||s.phase==='final-question'?`<div class="panel"><div class="panel-header"><h3>MASTER CLOCK</h3><span class="pill">SERVER SYNC</span></div>${clockHtml(s)}<div class="btn-row" style="margin-top:15px">${btn(s.timer.running?'PAUSE':'START',s.timer.running?'pause-timer':'start-timer','ghost',s.timer.running?'clock':'play')}${btn('RESET','reset-timer','ghost','refresh')}</div></div>`:''}<div class="panel"><div class="panel-header"><h3>PLAYER LOBBY</h3><span class="pill">${s.players.length} JOINED</span></div><div class="people-wrap">${s.players.length?s.players.map(p=>`<span class="player-chip"><span class="dot ${p.online?'green':'red'}"></span>${esc(p.name)}</span>`).join(''):'<span class="smallprint">Players will appear here as they join.</span>'}</div></div><div class="panel"><div class="panel-header"><h3>STUDIO SETTINGS</h3></div><div class="field"><label>VISUAL THEME</label><select data-live-theme>${Object.entries(A.themes).map(([key,t])=>`<option value="${key}" ${s.theme===key?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div class="divider"></div><div class="btn-row">${btn('SOUND: '+(localStorage.getItem('gridline:mute')==='1'?'OFF':'ON'),'toggle-sound','ghost','sound')}${btn('HELP','help-go','ghost','info')}</div></div></aside></div></div>`;}
function hostControls(s){const b=(label,type,variant='ghost',icon='',more='')=>`<button class="btn ${variant}" data-action="command" data-cmd="${type}" ${more}>${icon?ico(icon):''}${label}</button>`;const done=s.usedCount===s.totalCount;
 if(s.phase==='lobby')return `<div class="stack"><p class="smallprint">Invite your players, then start the event. Players can also join after the game begins when allowed in settings.</p>${b('START THE GAME','start','primary','play')}${btn('RENAME LIVE TEAM','rename-live-team','ghost','edit')}</div>`;
 if(s.phase==='board')return `<div class="stack"><p class="smallprint">${done?'All clues completed. Choose your next move.':'Choose a value from the board to present a clue.'}</p>${done?`${s.roundIndex<s.roundCount-1?b('NEXT ROUND','nextRound','primary','arrow'):''}${s.roundIndex===s.roundCount-1&&s.game.settings.finalEnabled&&s.game.final.question?b('START FINAL ROUND','startFinal','primary','bolt'):''}${b('FINISH THE GAME','end','ghost','check')}`:`<span class="pill">${s.totalCount-s.usedCount} QUESTIONS REMAIN</span>`}</div>`;
 if(s.phase==='question'){const teamOptions=s.teams.map(t=>`<option value="${t.id}" ${t.id===(s.players.find(p=>p.id===s.buzzerWinner)?.teamId||s.teams[0].id)?'selected':''}>${esc(t.name)}</option>`).join('');return `<div class="stack"><div class="command-grid">${b(s.buzzerOpen?'CLOSE BUZZERS':'OPEN BUZZERS',s.buzzerOpen?'closeBuzz':'openBuzz','ghost','bolt',s.answerRevealed||s.buzzerWinner?'disabled':'')}${b('REVEAL ANSWER','reveal','ghost','info',s.answerRevealed?'disabled':'')}</div><div class="field"><label>JUDGE TEAM ${s.buzzerWinner?'(BUZZ WINNER SELECTED)':''}</label><select id="judge-team">${teamOptions}</select></div><div class="command-grid">${b('CORRECT','judge','good','check','data-correct="true" '+(s.answerRevealed?'disabled':''))}${b('INCORRECT','judge','danger','x','data-correct="false" '+(s.answerRevealed?'disabled':''))}</div><div class="divider" style="margin:3px 0"></div>${b('CLOSE & NEXT QUESTION','complete','primary','arrow')}</div>`;}
 if(s.phase==='final-wager')return `<div class="stack"><p class="smallprint">Players submit their team wagers privately. ${s.submittedWagers.length}/${s.teams.length} teams have wagered.</p>${b('LOCK WAGERS • REVEAL QUESTION','lockWagers','primary','arrow')}</div>`;
 if(s.phase==='final-question')return `<div class="stack"><p class="smallprint">Players can submit private final answers. ${s.submittedFinalAnswers.length} submissions received.</p>${b('REVIEW SUBMISSIONS','reviewFinal','primary','arrow')}</div>`;
 if(s.phase==='final-judging')return `<div class="stack">${s.teams.map(t=>`<div class="panel" style="padding:12px"><b>${esc(t.name)}</b><p class="smallprint">WAGER ${s.wagers[t.id]??0} / ANSWER: ${esc(s.finalAnswers[t.id]||'NOT SUBMITTED')}</p>${s.finalJudged[t.id]===undefined?`<div class="btn-row"><button class="btn small good" data-action="command" data-cmd="judgeFinal" data-id="${t.id}" data-correct="true">CORRECT</button><button class="btn small danger" data-action="command" data-cmd="judgeFinal" data-id="${t.id}" data-correct="false">INCORRECT</button></div>`:`<span class="pill">JUDGED ${s.finalJudged[t.id]?'CORRECT':'INCORRECT'}</span>`}</div>`).join('')}${b('ANNOUNCE THE WINNERS','end','primary','check')}</div>`;
 return '';
}
function finalDisplay(s,host=false){return `<div class="question-display"><div class="eyebrow">THE FINAL STRETCH</div><h2 class="display h2" style="margin:18px 0">${esc(s.finalCategory)}</h2>${s.phase==='final-wager'?`<div class="pill">WAGER SUBMISSIONS OPEN</div><p class="muted">${s.submittedWagers.length} / ${s.teams.length} TEAMS READY</p>`:s.phase==='final-question'?`<h2>${esc(s.finalQuestion||'Final question...')}</h2><div class="pill">${s.submittedFinalAnswers.length} ANSWERS SUBMITTED</div>`:`<h2>${esc(s.finalQuestion||'Final question')}</h2><div class="answer-key"><strong>${host?'HOST-ONLY FINAL ANSWER':s.finalAnswer?'CORRECT ANSWER':'WAITING FOR REVEAL'}</strong><span>${esc(host?s.game.final.answer:s.finalAnswer||'')}</span></div>`}</div>`;}
function resultsDisplay(s,compact=false){const winner=s.standings.filter(t=>t.rank===1);return `<div><div class="results-hero"><div class="eyebrow">${s.phase==='results'?'THE FINAL CLASSIFICATION':'GAME RESULTS'}</div><h2 class="display" style="margin:20px auto">${winner.length===1?esc(winner[0]?.name||'NO WINNER'):'SHARED VICTORY'}</h2><div class="pill">${winner.length>1?'JOINT WINNERS':'CHAMPIONS OF THE GRID'}</div></div><div style="margin-top:23px">${s.standings.map(t=>`<div class="results-row"><div class="rank">${String(t.rank).padStart(2,'0')}</div><div><h3>${esc(t.name)}</h3><div class="smallprint">${t.rank===1?'THE CHAMPION':'FINAL RANK '+t.rank}</div></div><div class="score-number">${t.score}</div></div>`).join('')}</div><div class="btn-row" style="margin-top:22px">${btn('EXPORT RESULTS CSV','results-csv','primary','download')}${btn('COPY RESULT LINK','copy-results','ghost','link')}${compact?btn('MY GAME LIBRARY','studio-go','ghost','back'):''}</div></div>`;}
function stage(){const s=A.session;if(!s)return '<div class="shell pad-y">Connecting to presentation...</div>';return `<div class="stage-container"><div class="stage-brand">${logo()}<div class="flex"><span class="pill"><span class="dot green"></span> ${esc(s.code)}</span><span class="pill">${esc(s.roundTitle||'FINAL')}</span>${btn('FULLSCREEN','fullscreen','ghost','expand')}${btn('CLOSE','close-stage','ghost','x')}</div></div>${s.phase==='lobby'?lobby(s):s.phase==='board'?boardGrid(s):s.phase==='question'?selectedQuestion(s,true):s.phase.startsWith('final')?finalDisplay(s):resultsDisplay(s)}${s.phase==='question'||s.phase==='final-question'?`<div style="margin-top:15px;text-align:center">${clockHtml(s)}</div>`:''}<div class="stage-scores">${s.standings.map(t=>`<div class="team-score" style="--team-color:${esc(t.color)}"><div class="team-name">${esc(t.name)}</div><div class="score-number">${t.score}</div></div>`).join('')}</div><div class="smallprint" style="text-align:center;padding:20px">EVERY ANSWER CHANGES THE GAME &nbsp; / &nbsp; GRIDLINE STUDIO</div></div>`;}
function playerView(){const code=codeFromRoute();if(!code)return `<div class="shell"><div class="join-container"><div class="eyebrow">JOIN THE SHOW</div><h1 class="display h1" style="margin:18px 0">ENTER<br><span class="accent">THE GRID.</span></h1><form data-form="lookup" class="join-panel stack"><div class="field"><label>6-CHARACTER SESSION CODE</label><input name="code" placeholder="A2B4C6" maxlength="6" minlength="6" pattern="[A-Za-z0-9]{6}" style="font:900 32px var(--mono);letter-spacing:.2em;text-transform:uppercase;text-align:center" required/></div><button type="submit" class="btn primary wide">FIND YOUR SESSION ${ico('arrow')}</button></form></div></div>`;
 const s=A.session;if(!s)return `<div class="shell pad-y"><div class="eyebrow">CONNECTING TO ${esc(code)}</div></div>`;
 let saved;try{saved=JSON.parse(localStorage.getItem(`gridline:player:${code}`)||'null');}catch{}
 if(!saved)return `<div class="shell"><div class="join-container"><div class="eyebrow">JOIN SESSION / ${esc(code)}</div><h1 class="display h2" style="margin:15px 0 30px">PICK YOUR <span class="accent">SIDE.</span></h1><form class="join-panel stack" data-form="join-player"><div class="eyebrow">${esc(s.gameTitle)}</div><div class="field"><label>YOUR DISPLAY NAME</label><input name="name" maxlength="28" placeholder="Enter your name" autocomplete="nickname" required/></div><div class="field"><label>YOUR TEAM</label><select name="teamId" required>${s.teams.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div><button class="btn primary wide" type="submit">JOIN THE LOBBY ${ico('arrow')}</button><div class="smallprint">No account needed. Your device remembers this session for reconnecting.</div></form></div></div>`;
 const mine=s.players.find(p=>p.id===saved.id),team=s.teams.find(t=>t.id===saved.teamId),score=s.scores[saved.teamId]||0;
 const locked=s.buzzerWinner&&s.buzzerWinner!==saved.id,canBuzz=s.phase==='question'&&s.buzzerOpen&&!s.lockedOut.includes(saved.id)&&!s.buzzerWinner;
 return `<div class="shell"><div class="player-screen"><div class="spread"><div>${logo()}<div class="smallprint">PLAYER TERMINAL / ${esc(code)}</div></div><span class="pill"><span class="dot green"></span> CONNECTED</span></div><div class="player-stats"><div class="eyebrow">${esc(mine?.name||saved.name)} &nbsp; • &nbsp; ${esc(team?.name||'YOUR TEAM')}</div><h1 class="display h1" style="margin:17px 0 10px">${esc(s.gameTitle)}</h1><div class="flex" style="justify-content:center"><span class="pill">SCORE ${score}</span><span class="pill">${esc(s.phase.replaceAll('-',' ').toUpperCase())}</span></div></div>${s.phase==='lobby'?`<div class="panel" style="text-align:center;padding:45px 20px"><span class="eyebrow">YOU'RE ON THE GRID</span><h2 class="display h2" style="margin:15px 0">WAITING FOR LIGHTS OUT.</h2><p class="muted">The host will start the game. Keep this screen open.</p></div>`:s.phase==='results'?resultsDisplay(s):s.phase==='final-wager'?`<form class="panel stack" data-form="wager"><div class="eyebrow">FINAL ROUND / PLACE YOUR BET</div><h2 class="display h3">${esc(s.finalCategory)}</h2><p class="muted">Your team can wager up to ${Math.max(1000,score)} points. One wager per team.</p><div class="field"><label>YOUR WAGER</label><input type="number" name="wager" min="0" max="${Math.max(1000,score)}" value="0" required/></div><button class="btn primary wide" ${s.submittedWagers.includes(saved.teamId)?'disabled':''}>${s.submittedWagers.includes(saved.teamId)?'WAGER SUBMITTED':'LOCK IN WAGER'}</button></form>`:s.phase==='final-question'?`<form class="panel stack" data-form="final-answer"><div class="eyebrow">FINAL QUESTION</div><h2 style="font-size:27px">${esc(s.finalQuestion)}</h2>${clockHtml(s)}<div class="field"><label>YOUR TEAM'S FINAL ANSWER</label><textarea name="answer" maxlength="500" required></textarea></div><button class="btn primary wide" ${s.submittedFinalAnswers.includes(saved.teamId)?'disabled':''}>${s.submittedFinalAnswers.includes(saved.teamId)?'ANSWER SUBMITTED':'SUBMIT FINAL ANSWER'}</button></form>`:s.phase==='final-judging'?`<div class="panel" style="text-align:center"><h2 class="display h3">THE VERDICT IS IN.</h2><p class="muted">The host is reviewing final answers.</p></div>`:`<div class="player-question">${s.phase==='question'?esc(s.question?.prompt||''):s.phase==='board'?'THE BOARD IS LIVE': 'STAND BY FOR THE NEXT CLUE'}</div><div class="buzzer-zone"><button class="buzzer" data-action="buzz" ${canBuzz?'':'disabled'} aria-label="Buzz in"><small>${canBuzz?'NOW IS YOUR MOMENT':'PLAYER BUZZER'}</small><b>${canBuzz?'BUZZ!':s.buzzerWinner===saved.id?'LOCKED':'WAIT'}</b><small>${canBuzz?'TAP TO LOCK IN':s.buzzerWinner===saved.id?'YOU WERE FIRST':locked?'ANOTHER PLAYER WAS FIRST':'AWAITING HOST'}</small></button></div><div class="player-message">${canBuzz?'BUZZERS ARE LIVE • REACT FAST':s.buzzerWinner===saved.id?'YOU ARE FIRST! WAIT FOR THE HOST':locked?'ANOTHER PLAYER IS ANSWERING':s.phase==='board'?'WAIT FOR THE NEXT QUESTION':s.lockedOut.includes(saved.id)?'YOU ARE LOCKED OUT FOR THIS QUESTION':'STAND BY FOR THE GREEN LIGHT'}</div>`}<div class="panel" style="margin-top:27px"><div class="panel-header"><h3>THE STANDINGS</h3></div>${teamBoard(s)}</div></div></div>`;
}
function themeStudio(){const selected=localStorage.getItem('gridline:theme')||'papaya',palette=A.custom||A.themes[selected]||A.themes.papaya;const tokens=['bg','elev','card','border','text','muted','accent','accent2','board','tile','good','bad'];return `<div class="shell pad-y" style="padding-top:0"><div class="page-head">${titleBlock('THE THEME LAB / PRECISION COLOR','EVERY DETAIL. <span class="accent">YOUR CALL.</span>','Eight individually designed colorways. An editable live palette. Zero generic filters.') }<div class="btn-row">${btn('RESET COLORS','reset-colors','ghost','refresh')}${btn('EXPORT THEME','export-theme','primary','download')}</div></div><div class="section-heading"><div><div class="eyebrow">01 / FACTORY EDITIONS</div><h2 class="display h3" style="margin:10px 0">PICK A STARTING POINT.</h2></div></div><div class="grid4">${Object.entries(A.themes).map(([id,t])=>`<button class="theme-card ${id===selected&&!A.custom?'selected':''}" data-action="pick-theme" data-id="${id}"><div class="theme-swatch" style="background:${t.bg}"><i style="background:${t.card}"></i><i style="background:${t.tile}"></i><i style="background:${t.accent}"></i><i style="background:${t.accent2}"></i></div><strong>${esc(t.name)}</strong><small>${id===selected&&!A.custom?'CURRENT THEME • ':'PREVIEW & APPLY'}</small></button>`).join('')}</div><div class="section" style="padding-bottom:10px"><div class="section-heading"><div><div class="eyebrow">02 / STUDIO CUSTOMIZER</div><h2 class="display h3" style="margin:12px 0">TUNE THE PALETTE.</h2><p class="muted">Change any token to see it update immediately throughout the interface.</p></div>${A.user?btn('SAVE AS A NAMED PRESET','save-preset','primary','check'):btn('SIGN IN TO SAVE PRESETS','studio-go','ghost','arrow')}</div><div class="panel"><div class="color-grid">${tokens.map(k=>`<label class="color-field"><input type="color" data-color="${k}" value="${esc(palette[k])}" aria-label="${k} color"><span>${k.replace(/([A-Z])/g,' $1').toUpperCase()}<br><span class="mono" data-hex="${k}">${esc(palette[k])}</span></span></label>`).join('')}</div><div class="divider"></div><div class="btn-row">${btn('EXPORT CURRENT PALETTE','export-theme','ghost','download')}${btn('IMPORT THEME JSON','import-theme','ghost','copy')}</div></div></div><div class="section-heading" style="margin-top:34px"><div><div class="eyebrow">03 / YOUR COLLECTION</div><h2 class="display h3" style="margin:12px 0">SAVED PRESETS.</h2></div></div><div class="grid3">${(A.presets||[]).length?(A.presets||[]).map(p=>`<div class="panel"><div class="spread"><b>${esc(p.name)}</b><span class="dot green"></span></div><div class="theme-swatch" style="background:${esc(p.tokens.bg)};margin:13px 0"><i style="background:${esc(p.tokens.card)}"></i><i style="background:${esc(p.tokens.accent)}"></i></div><div class="btn-row">${btn('APPLY','apply-preset','primary','check',`data-id="${p.id}"`)}${btn('DELETE','delete-preset','danger','trash',`data-id="${p.id}"`)}</div></div>`).join(''):'<div class="panel"><p class="muted">No saved presets yet. Create your own above.</p></div>'}</div></div>`;}
function help(){return `<div class="shell pad-y" style="padding-top:0"><div class="page-head">${titleBlock('YOUR OPERATIONS MANUAL','MASTER THE STUDIO.','Everything you need to host a professional quiz night without writing any code.')}<div>${btn('START A GAME','studio-go','primary','arrow')}</div></div><div class="grid2"><div class="panel"><div class="eyebrow">01 / CREATE</div><h2 class="display h3" style="margin:15px 0">BUILD A GAME.</h2><p class="muted">In the Studio, create a blank quiz or choose a template. Rename categories, edit every question and answer, configure timers, enable final rounds and customize your theme. Edits autosave to Cloudflare D1.</p></div><div class="panel"><div class="eyebrow">02 / LAUNCH</div><h2 class="display h3" style="margin:15px 0">BRING PLAYERS IN.</h2><p class="muted">Launch a quiz to get a six-character code. Share the join link. Players can join from their own phones without creating an account. Open the presentation in a second window to show your audience.</p></div><div class="panel"><div class="eyebrow">03 / HOST</div><h2 class="display h3" style="margin:15px 0">CONTROL THE SHOW.</h2><p class="muted">Select a question, run the timer, open buzzing, judge the winning team and complete the clue. Scores update on every connected screen. Wrong-answer deductions and manual corrections are configurable.</p></div><div class="panel"><div class="eyebrow">04 / FINISH</div><h2 class="display h3" style="margin:15px 0">TAKE THE PODIUM.</h2><p class="muted">When every tile is complete, progress to the next round or run a final-wager question. Reveal the results, export rankings and keep your original quiz to play again.</p></div></div><div class="section-heading" style="margin-top:60px"><div><div class="eyebrow">POWER USER / SHORTCUTS</div><h2 class="display h3" style="margin:13px 0">KEYBOARD RACE CONTROL.</h2></div></div><div class="panel"><div class="grid2">${[['T','START / PAUSE THE CLOCK'],['B','TOGGLE BUZZERS'],['A','REVEAL CORRECT ANSWER'],['C','JUDGE SELECTED TEAM CORRECT'],['X','JUDGE SELECTED TEAM INCORRECT'],['R','COMPLETE CURRENT CLUE'],['F','TOGGLE FULLSCREEN'],['ESC','CLOSE ACTIVE DIALOG']].map(([k,label])=>`<div class="spread" style="border-bottom:1px solid var(--border);padding:14px 0"><span class="smallprint">${label}</span><kbd class="keyboard">${k}</kbd></div>`).join('')}</div><p class="smallprint">Shortcuts are disabled while typing inside form fields.</p></div><div class="section-heading" style="margin-top:60px"><div><div class="eyebrow">HEALTH & DIAGNOSTICS</div><h2 class="display h3" style="margin:13px 0">SYSTEM STATUS.</h2></div>${btn('REFRESH CHECK','health','ghost','refresh')}</div><div class="panel"><div class="grid3"><div><div class="statline">BACKEND</div><h3>${A.health?.ok?'CONNECTED':'CHECKING'}</h3></div><div><div class="statline">DATABASE</div><h3>${A.health?.database?'READY':'CHECKING'}</h3></div><div><div class="statline">APPLICATION</div><h3>${esc(A.health?.version||'0.8.0')}</h3></div></div><p class="smallprint">Cloudflare Workers + D1 + hibernating Durable Object WebSockets. Free-tier usage limits apply.</p></div></div>`;}
function modalContent(){if(!A.modal)return '';
 if(A.modal==='auth'){return `<div class="modal-backdrop" data-dismiss="1"><div class="modal" role="dialog" aria-modal="true" aria-label="Host account"><div class="modal-top"><span class="eyebrow">THE CONTROL ROOM</span><button class="btn small ghost" data-action="close-modal" aria-label="Close">${ico('x')}</button></div>${authForm(A.authMode||'register')}</div></div>`;}
 if(A.modal==='question'){
  const details=questionById(A.draft,A.editingQuestion);if(!details)return '';
  const {q,c}=details;return `<div class="modal-backdrop" data-dismiss="1"><div class="modal" role="dialog" aria-modal="true" aria-label="Edit question"><div class="modal-top"><div class="eyebrow">QUESTION EDITOR / ${esc(c.name)}</div><button class="btn small ghost" data-action="close-modal" aria-label="Close">${ico('x')}</button></div><h2>MAKE IT COUNT.</h2><div class="stack"><div class="form-row"><div class="field"><label>POINT VALUE</label><input type="number" min="1" max="1000000" data-qfield="value" value="${q.value}"/></div><div class="field"><label>TIME LIMIT / SECONDS</label><input type="number" min="5" max="3600" data-qfield="timeLimit" value="${q.timeLimit||30}"/></div></div><div class="field"><label>THE QUESTION / CLUE</label><textarea data-qfield="prompt" rows="4" maxlength="2500" placeholder="Write your question here...">${esc(q.prompt)}</textarea></div><div class="field"><label>CORRECT ANSWER / HOST ONLY</label><input data-qfield="answer" maxlength="1200" value="${esc(q.answer)}" placeholder="What is the correct answer?"/></div><div class="field"><label>EXPLANATION (OPTIONAL)</label><textarea data-qfield="explanation" placeholder="Additional context for the reveal...">${esc(q.explanation||'')}</textarea></div><div class="form-row"><div class="field"><label>DIFFICULTY</label><select data-qfield="difficulty">${['easy','medium','hard'].map(v=>`<option ${q.difficulty===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>IMAGE URL (HTTPS, OPTIONAL)</label><input type="url" data-qfield="imageUrl" value="${esc(q.imageUrl||'')}" placeholder="https://..."/></div></div></div><div class="modal-actions"><button class="btn danger" data-action="remove-question">${ico('trash')} DELETE QUESTION</button><button class="btn ghost" data-action="duplicate-question">${ico('copy')} DUPLICATE</button><button class="btn primary" data-action="edit-saveclose">${ico('check')} SAVE & CLOSE</button></div></div></div>`;}
 return '';
}
function render(){const p=openRoute();document.body.classList.toggle('stage-view',/^\/session\/[A-Z0-9]{6}\/stage$/i.test(p));document.body.classList.toggle('race',A.race);routeTheme();let content;if(p==='/')content=home();else if(p==='/studio')content=studio();else if(p==='/templates')content=templateGallery();else if(p==='/themes')content=themeStudio();else if(p==='/help')content=help();else if(/^\/game\/[a-z0-9-]+\/edit$/i.test(p))content=editor();else if(/^\/session\/[A-Z0-9]{6}\/control$/i.test(p))content=hostSession();else if(/^\/session\/[A-Z0-9]{6}\/stage$/i.test(p))content=stage();else if(/^\/session\/[A-Z0-9]{6}\/results$/i.test(p))content=`<main class="shell pad-y">${A.session?resultsDisplay(A.session):'<div>Loading results...</div>'}</main>`;else if(p==='/join'||/^\/join\/[A-Z0-9]{6}$/i.test(p))content=playerView();else content=`<div class="shell pad-y"><h1 class="display h1">OFF THE GRID.</h1><p class="muted">This page does not exist.</p>${btn('BACK HOME','home-go','primary','arrow')}</div>`;
 $('#app').innerHTML=(p.match(/^\/session\/\w{6}\/stage$/i)?'':header())+content+(p.match(/^\/session\/\w{6}\/stage$/i)?'':footer());$('#modal-root').innerHTML=modalContent();updateClock();}
async function loadNavigate(){const p=openRoute();A.menu=false;
 try{
  const ed=p.match(/^\/game\/([a-z0-9-]+)\/edit$/i);if(ed){if(A.draft?.id!==ed[1]){A.draft=await api('/api/games/'+ed[1]);A.editorRound=0;A.saveFlag='ALL CHANGES SAVED';}}
  if(p==='/studio'&&A.user)A.games=await api('/api/games');
  if(p==='/themes'&&A.user)A.presets=await api('/api/presets');
  if(p==='/help')A.health=await api('/api/health');
  const code=codeFromRoute();if(code){const role=p.endsWith('/control')||p.endsWith('/results')?'host':'public';A.session=await api(`/api/sessions/${code}${role==='host'?'/host':''}`);A.liveRole=role;attachLive(code);}else{if(A.liveClose)A.liveClose();A.liveCode=null;A.session=null;}
  render();window.scrollTo({top:0,behavior:'instant'});
 }catch(err){toast(err.message,true);$('#app').innerHTML=header()+`<main class="shell pad-y"><div class="eyebrow">CONNECTION ERROR</div><h1 class="display h2">CAN'T FIND THE GRID.</h1><p class="muted">${esc(err.message)}</p>${btn('RETURN HOME','home-go','primary','arrow')}</main>`+footer();}
}
async function nav(p){if(location.pathname!==p)history.pushState({},'',p);await loadNavigate();}
function attachLive(code){
 if(A.liveCode===code&&A.es)return;
 if(A.es){A.es.onclose=null;A.es.close();}A.liveCode=code;
 let retries=0,closed=false;
 const connect=()=>{
  if(closed||A.liveCode!==code)return;
  const proto=location.protocol==='https:'?'wss:':'ws:';
  const ws=new WebSocket(`${proto}//${location.host}/api/sessions/${code}/events`);
  A.es=ws;
  ws.onopen=()=>{retries=0;refreshSession().catch(e=>console.warn('Snapshot pending',e));};
  ws.onmessage=async ev=>{try{const meta=JSON.parse(ev.data);if(meta.kind==='connected')return;
   if(A.session&&meta.revision<A.session.revision)return;
   if(codeFromRoute()!==code)return;
   const role=/\/control$|\/results$/.test(location.pathname)?'host':'public';
   A.session=await api(`/api/sessions/${code}${role==='host'?'/host':''}`);
   A.serverOffset=Date.now()-A.session.serverNow;
   if(codeFromRoute()===code){const focus=document.activeElement?.name||document.activeElement?.id;render();if(focus&&['wager','answer'].includes(focus))$(`[name=${focus}]`)?.focus();}
  }catch(e){console.warn('Waiting for connection',e);}};
  ws.onclose=()=>{if(closed||A.liveCode!==code)return;const ms=Math.min(12000,600*2**Math.min(retries++,5));setTimeout(connect,ms);};
  ws.onerror=()=>{};
 };
 connect();
 A.liveClose=()=>{closed=true;const w=A.es;A.es=null;if(w){w.onclose=null;w.close();}};
}
function updateClock(){const s=A.session;if(!s?.timer)return;const serverTime=Date.now()-(A.serverOffset||0);const text=formatClock(s.timer,serverTime);$$('[data-clock]').forEach(el=>{el.textContent=text;el.classList.toggle('warning',!/^00:1|^00:[2-5]/.test(text)&&s.timer.running);});const rem=s.timer.running?Math.max(0,(s.timer.deadline-serverTime)/1000):s.timer.remaining;$$('[data-clock-track]').forEach(el=>el.style.width=Math.max(0,Math.min(100,rem/s.timer.duration*100))+'%');}
setInterval(updateClock,250);
setInterval(async()=>{const code=codeFromRoute();if(code&&location.pathname.startsWith('/join/')&&localStorage.getItem(`gridline:player:${code}`)){try{await api(`/api/sessions/${code}/heartbeat`,{method:'POST',body:{}});}catch{}}},25000);
function sound(freq=660){if(localStorage.getItem('gridline:mute')==='1')return;try{const AudioContext=window.AudioContext||window.webkitAudioContext;const ac=new AudioContext(),o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.setValueAtTime(freq,ac.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(100,freq*.65),ac.currentTime+.15);g.gain.setValueAtTime(.0001,ac.currentTime);g.gain.exponentialRampToValueAtTime(.045,ac.currentTime+.015);g.gain.exponentialRampToValueAtTime(.0001,ac.currentTime+.22);o.connect(g).connect(ac.destination);o.start();o.stop(ac.currentTime+.23);o.onended=()=>ac.close();}catch{}}
function dirty(){A.saveFlag='UNSAVED CHANGES';$('#save-status')&&($('#save-status').textContent=A.saveFlag);clearTimeout(A.saveTimer);A.saveTimer=setTimeout(()=>saveGame(true),850);}
function newQuestion(value=200){return {id:uid(),prompt:'',answer:'',value,explanation:'',timeLimit:30,imageUrl:'',difficulty:'medium'};}
function cleanGame(g){const {id,createdAt,updatedAt,archived,...rest}=g;return JSON.parse(JSON.stringify(rest));}
async function saveGame(silent=false){if(!A.draft)return;clearTimeout(A.saveTimer);A.saveFlag='SAVING...';$('#save-status')&&($('#save-status').textContent=A.saveFlag);try{const saved=await api('/api/games/'+A.draft.id,{method:'PUT',body:cleanGame(A.draft)});A.draft.updatedAt=saved.updatedAt;A.saveFlag='SAVED TO DATABASE';if(!silent)toast('Game saved successfully');}catch(e){A.saveFlag='SAVE FAILED';toast(e.message,true);}$('#save-status')&&($('#save-status').textContent=A.saveFlag);}
async function newGame(opts){if(!A.user){A.modal='auth';A.authMode='register';render();return;}const g=await api('/api/games',{method:'POST',body:opts});A.draft=null;await nav(`/game/${g.id}/edit`);toast('New game is ready to edit');}
async function command(cmd){const code=codeFromRoute();if(!code||A.working)return;A.working=true;try{const update=await api(`/api/sessions/${code}/command`,{method:'POST',body:{...cmd,commandId:uid()}});A.session=update;A.serverOffset=Date.now()-update.serverNow;render();if(cmd.type==='judge'||cmd.type==='judgeFinal')sound(cmd.correct?1000:220);else if(['select','start','end'].includes(cmd.type))sound(710);}catch(e){toast(e.message,true);}finally{A.working=false;}}
async function refreshLibrary(){if(A.user)A.games=await api('/api/games');}
async function copyValue(value){try{await navigator.clipboard.writeText(value);toast('Copied to clipboard');}catch{const input=document.createElement('textarea');input.value=value;document.body.append(input);input.select();try{document.execCommand('copy');toast('Copied to clipboard');}finally{input.remove();}}}
function liveJoinUrl(){return `${location.origin}/join/${codeFromRoute()}`;}
function parseCSV(text){let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('CSV file has an unclosed quotation');row.push(cell);if(row.some(v=>v.trim()))rows.push(row);return rows;}
function csvToGame(text){const rows=parseCSV(text.replace(/^\uFEFF/,''));if(rows.length<2)throw Error('CSV needs a header and at least one question');const headers=rows.shift().map(h=>h.trim().toLowerCase());const idx=(...alts)=>alts.map(h=>headers.indexOf(h)).find(i=>i>=0);const ci=idx('category','category name'),qi=idx('question','prompt','clue'),ai=idx('answer','correct answer'),vi=idx('value','points'),ri=idx('round');if(qi===undefined||ai===undefined)throw Error('CSV must include Question and Answer columns');const g=structuredClone(A.templates[0].game);g.title='Imported Quiz';g.settings.finalEnabled=false;g.rounds=[];const roundMap=new Map();for(const row of rows){const prompt=(row[qi]||'').trim(),answer=(row[ai]||'').trim(),category=(row[ci]||'GENERAL').trim()||'GENERAL',round=(row[ri]||'ROUND 01').trim()||'ROUND 01',v=Number(row[vi]||200);if(!prompt||!answer)throw Error('Every CSV row needs a question and an answer');if(!Number.isSafeInteger(v)||v<=0)throw Error('Question values must be positive whole numbers');if(!roundMap.has(round)){if(roundMap.size>=8)throw Error('Maximum 8 rounds in one quiz');roundMap.set(round,{id:uid(),title:round,categories:[]});}const r=roundMap.get(round);let c=r.categories.find(c=>c.name.toLowerCase()===category.toLowerCase());if(!c){if(r.categories.length>=10)throw Error('Maximum 10 categories per round');c={id:uid(),name:category,questions:[]};r.categories.push(c);}if(c.questions.length>=10)throw Error('Maximum 10 questions per category');c.questions.push({...newQuestion(v),prompt,answer,value:v});}g.rounds=[...roundMap.values()];return g;}
async function handleAction(button){const action=button.dataset.action,id=button.dataset.id,code=codeFromRoute();
 switch(action){
 case 'menu':A.menu=!A.menu;render();break;
 case 'home-go':await nav('/');break;
 case 'studio-go':if(!A.user){A.modal='auth';A.authMode='register';render();}else await nav('/studio');break;
 case 'join-go':await nav('/join');break;
 case 'templates-go':await nav('/templates');break;
 case 'help-go':await nav('/help');break;
 case 'close-modal':A.modal=null;render();break;
 case 'auth-toggle':A.authMode=A.authMode==='register'?'login':'register';A.modal='auth';render();break;
 case 'demo':{button.disabled=true;toast('Creating isolated interactive demonstration...');const {code,token}=await api('/api/demo',{method:'POST',body:{}});localStorage.setItem(`gridline:demo:${code}`,token);await nav(`/session/${code}/control`);break;}
 case 'create-blank':await newGame({blank:true});break;
 case 'use-template':await newGame({templateId:id});break;
 case 'launch':{const gameId=id||A.draft?.id;if(!gameId)return;if(A.draft?.id===gameId)await saveGame(true);const g=await api(`/api/games/${gameId}/launch`,{method:'POST',body:{}});await nav(`/session/${g.code}/control`);toast(`Live session ${g.code} created`);break;}
 case 'clone':await api(`/api/games/${id}/clone`,{method:'POST',body:{}});await refreshLibrary();render();toast('Quiz duplicated');break;
 case 'delete-game':{const g=A.games.find(g=>g.id===id);if(!confirm(`Archive "${g?.title||'this game'}"? Existing sessions will not be affected.`))return;await api(`/api/games/${id}`,{method:'DELETE',body:{}});await refreshLibrary();render();toast('Game archived');break;}
 case 'save-game':await saveGame();break;
 case 'edit-round':A.editorRound=Number(button.dataset.index);render();break;
 case 'add-round':{const g=A.draft;if(g.rounds.length>=8)throw Error('Maximum 8 rounds');const r={id:uid(),title:`ROUND ${String(g.rounds.length+1).padStart(2,'0')}`,categories:[{id:uid(),name:'NEW CATEGORY',questions:[1,2,3,4,5].map(i=>newQuestion(i*200))}]};g.rounds.push(r);A.editorRound=g.rounds.length-1;dirty();render();break;}
 case 'rename-round':{const r=A.draft.rounds[A.editorRound],name=prompt('Round name:',r.title);if(name?.trim()){r.title=name.trim().slice(0,70);dirty();render();}break;}
 case 'remove-round':{if(A.draft.rounds.length<=1)throw Error('Keep at least one round');if(!confirm('Delete this round and all questions?'))return;A.draft.rounds.splice(A.editorRound,1);A.editorRound=Math.max(0,A.editorRound-1);dirty();render();break;}
 case 'add-default-team':{const ts=A.draft.settings.teams;if(ts.length>=15)throw Error('Maximum 15 teams');ts.push({id:uid(),name:`TEAM ${ts.length+1}`,color:['#FF8000','#66A7FF','#58D4A1','#E2BD79','#CC83FF'][ts.length%5]});dirty();render();break;}
 case 'remove-default-team':{const ts=A.draft.settings.teams;if(ts.length<=1)throw Error('Keep at least one team');ts.splice(ts.findIndex(t=>t.id===id),1);dirty();render();break;}
 case 'add-category':{const r=A.draft.rounds[A.editorRound];if(r.categories.length>=10)throw Error('Maximum 10 categories per round');r.categories.push({id:uid(),name:`CATEGORY ${r.categories.length+1}`,questions:[1,2,3,4,5].map(i=>newQuestion(i*200))});dirty();render();break;}
 case 'shift-category':{const cs=A.draft.rounds[A.editorRound].categories,idx=cs.findIndex(c=>c.id===id),to=idx+Number(button.dataset.dir);if(to>=0&&to<cs.length){[cs[idx],cs[to]]=[cs[to],cs[idx]];dirty();render();}break;}
 case 'duplicate-category':{const cs=A.draft.rounds[A.editorRound].categories;if(cs.length>=10)throw Error('Maximum 10 categories');const c=cs.find(c=>c.id===id);cs.splice(cs.indexOf(c)+1,0,{...structuredClone(c),id:uid(),name:c.name+' COPY',questions:c.questions.map(q=>({...q,id:uid()}))});dirty();render();break;}
 case 'remove-category':{const cs=A.draft.rounds[A.editorRound].categories;if(cs.length===1)throw Error('Keep at least one category');if(!confirm('Delete this category and all its questions?'))return;cs.splice(cs.findIndex(c=>c.id===id),1);dirty();render();break;}
 case 'add-row':{const cs=A.draft.rounds[A.editorRound].categories;if(cs.some(c=>c.questions.length>=10))throw Error('Maximum 10 questions per category');cs.forEach(c=>c.questions.push(newQuestion((c.questions.length+1)*200)));dirty();render();break;}
 case 'add-question':{const c=A.draft.rounds[A.editorRound].categories.find(c=>c.id===id);if(c.questions.length>=10)throw Error('Maximum 10 questions per category');const q=newQuestion((c.questions.length+1)*200);c.questions.push(q);A.editingQuestion=q.id;A.modal='question';dirty();render();break;}
 case 'edit-question':A.editingQuestion=id;A.modal='question';render();break;
 case 'remove-question':{if(!confirm('Delete this question?'))return;const f=questionById(A.draft,A.editingQuestion);f.c.questions.splice(f.qi,1);A.modal=null;dirty();render();break;}
 case 'duplicate-question':{const f=questionById(A.draft,A.editingQuestion);if(f.c.questions.length>=10)throw Error('Maximum 10 questions per category');const q={...f.q,id:uid()};f.c.questions.splice(f.qi+1,0,q);A.editingQuestion=q.id;dirty();render();break;}
 case 'edit-saveclose':A.modal=null;await saveGame();render();break;
 case 'import-game':{const inp=document.createElement('input');inp.type='file';inp.accept='.json,.csv,application/json,text/csv';inp.onchange=async()=>{try{const file=inp.files?.[0];if(!file)return;const content=await file.text();if(file.name.toLowerCase().endsWith('.csv'))await newGame({game:csvToGame(content)});else{const parsed=JSON.parse(content);const game=parsed.game||parsed;const clean=cleanGame(game);if(!Array.isArray(clean.rounds))throw Error('JSON must contain GRIDLINE quiz rounds');await newGame({game:clean});}}catch(e){toast(e.message,true);}};inp.click();break;}
 case 'export-game':{const g=A.draft||A.games.find(g=>g.id===id);if(g)download(`gridline-${g.title.toLowerCase().replace(/[^a-z0-9]/g,'-')}.json`,cleanGame(g));break;}
 case 'export-questions':{const rows=[['Round','Category','Value','Question','Answer','Explanation']];for(const r of A.draft.rounds)for(const c of r.categories)for(const q of c.questions)rows.push([r.title,c.name,q.value,q.prompt,q.answer,q.explanation]);download('gridline-questions.csv',rows.map(row=>row.map(v=>`"${String(v||'').replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv');break;}
 case 'select-live':await command({type:'select',questionId:id});break;
 case 'command':{const type=button.dataset.cmd,params={type};if(type==='judge'){params.teamId=$('#judge-team')?.value||A.session.teams[0].id;params.correct=button.dataset.correct==='true';}if(type==='judgeFinal'){params.teamId=id;params.correct=button.dataset.correct==='true';}await command(params);break;}
 case 'start-timer':await command({type:'startTimer'});break;
 case 'pause-timer':await command({type:'pauseTimer'});break;
 case 'reset-timer':await command({type:'resetTimer'});break;
 case 'undo-score':await command({type:'undo'});break;
 case 'adjust-score':{const list=A.session.teams.map((t,i)=>`${i+1}. ${t.name}`).join('\n'),num=prompt(`Select a team number:\n${list}`);if(num===null)return;const team=A.session.teams[Number(num)-1];if(!team)throw Error('Invalid team number');const entered=prompt(`Adjust points for ${team.name} (negative to deduct):`,'200');if(entered===null)return;const delta=Number(entered);if(!Number.isSafeInteger(delta)||delta===0)throw Error('Enter a nonzero whole number');await command({type:'score',teamId:team.id,delta});break;}
 case 'rename-live-team':{const list=A.session.teams.map((t,i)=>`${i+1}. ${t.name}`).join('\n'),num=prompt(`Which team to rename?\n${list}`);if(num===null)return;const team=A.session.teams[Number(num)-1];if(!team)throw Error('Invalid team number');const name=prompt('New name for '+team.name+':',team.name);if(name?.trim())await command({type:'renameTeam',teamId:team.id,name:name.trim()});break;}
 case 'copy-join':await copyValue(liveJoinUrl());break;
 case 'copy-results':await copyValue(`${location.origin}/session/${code}/stage`);break;
 case 'open-player':window.open(`/join/${code}`,'_blank','noopener');break;
 case 'open-stage':window.open(`/session/${code}/stage`,'gridline-stage','width=1440,height=900');break;
 case 'close-stage':window.close();if(!window.closed)await nav(`/session/${code}/control`);break;
 case 'fullscreen':if(!document.fullscreenElement)await document.documentElement.requestFullscreen?.();else await document.exitFullscreen?.();break;
 case 'race-toggle':A.race=!A.race;localStorage.setItem('gridline:race',A.race?'1':'0');render();break;
 case 'toggle-sound':{const mute=localStorage.getItem('gridline:mute')==='1';localStorage.setItem('gridline:mute',mute?'0':'1');if(mute)sound();render();break;}
 case 'buzz':{button.disabled=true;button.querySelector('b').textContent='SENT';try{await api(`/api/sessions/${code}/buzz`,{method:'POST',body:{nonce:uid()}});sound(900);if(navigator.vibrate)navigator.vibrate(35);await refreshSession();}catch(e){toast(e.message,true);await refreshSession();}break;}
 case 'results-csv':{const s=A.session;download(`gridline-${s.code}-results.csv`,[['Rank','Team','Score'],...s.standings.map(t=>[t.rank,t.name,t.score])].map(row=>row.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n'),'text/csv');break;}
 case 'pick-theme':{if(!A.themes[id])throw Error('Invalid theme');A.custom=null;localStorage.removeItem('gridline:custom');localStorage.setItem('gridline:theme',id);if(A.user){A.prefs.theme=id;await api('/api/settings',{method:'PUT',body:A.prefs});}applyTheme(id);render();toast(`${A.themes[id].name} applied`);break;}
 case 'reset-colors':A.custom=null;localStorage.removeItem('gridline:custom');render();toast('Factory palette restored');break;
 case 'export-theme':download('gridline-theme.json',A.custom||A.themes[localStorage.getItem('gridline:theme')||'papaya']);break;
 case 'import-theme':{const inp=document.createElement('input');inp.type='file';inp.accept='.json';inp.onchange=async()=>{try{const t=JSON.parse(await inp.files[0].text());for(const k of ['bg','elev','card','border','text','muted','accent','accent2','board','tile','good','bad'])if(!/^#[a-f0-9]{6}$/i.test(t[k]||''))throw Error(`Invalid color for ${k}`);A.custom=t;localStorage.setItem('gridline:custom',JSON.stringify(t));render();toast('Theme imported');}catch(e){toast(e.message,true);}};inp.click();break;}
 case 'save-preset':{if(!A.user)throw Error('Sign in to save presets');const name=prompt('Name your custom Studio theme:','My Grand Prix');if(!name?.trim())return;const tokens=A.custom||A.themes[localStorage.getItem('gridline:theme')||'papaya'];await api('/api/presets',{method:'POST',body:{name:name.trim(),tokens}});A.presets=await api('/api/presets');render();toast('Custom theme saved');break;}
 case 'apply-preset':{const p=A.presets.find(p=>p.id===id);if(!p)return;A.custom=p.tokens;localStorage.setItem('gridline:custom',JSON.stringify(p.tokens));render();toast('Preset applied');break;}
 case 'delete-preset':{if(!confirm('Delete this theme preset?'))return;await api('/api/presets/'+id,{method:'DELETE',body:{}});A.presets=await api('/api/presets');render();toast('Preset deleted');break;}
 case 'health':A.health=await api('/api/health');render();toast('Backend and database checked');break;
 }
}
async function refreshSession(){const code=codeFromRoute();if(!code)return;const role=/\/control$|\/results$/.test(location.pathname)?'host':'public';A.session=await api(`/api/sessions/${code}${role==='host'?'/host':''}`);A.serverOffset=Date.now()-A.session.serverNow;render();}
async function handleForm(form){const data=Object.fromEntries(new FormData(form).entries()),type=form.dataset.form;
 if(type==='register'||type==='login'){const user=await api(`/api/auth/${type}`,{method:'POST',body:data});A.user=user;A.modal=null;A.draft=null;A.games=await api('/api/games');await nav('/studio');toast(type==='register'?'Your GRIDLINE studio is ready':'Welcome back to your studio');return;}
 if(type==='lookup'){const code=String(data.code||'').toUpperCase();if(!/^[A-Z0-9]{6}$/.test(code))throw Error('Enter a valid 6-character code');await nav('/join/'+code);return;}
 const code=codeFromRoute();
 if(type==='join-player'){const p=await api(`/api/sessions/${code}/join`,{method:'POST',body:data});localStorage.setItem(`gridline:player:${code}`,JSON.stringify(p));A.player=p;await refreshSession();sound(650);toast(`Joined as ${p.name}`);return;}
 if(type==='wager'){await api(`/api/sessions/${code}/wager`,{method:'POST',body:{wager:Number(data.wager)}});await refreshSession();toast('Wager locked in');return;}
 if(type==='final-answer'){await api(`/api/sessions/${code}/answer`,{method:'POST',body:{answer:data.answer}});await refreshSession();toast('Final answer submitted');return;}
}
document.addEventListener('click',async e=>{
 const link=e.target.closest('a[data-link]');if(link){e.preventDefault();await nav(new URL(link.href).pathname);return;}
 const navEl=e.target.closest('[data-nav]');if(navEl){e.preventDefault();await nav(navEl.dataset.nav);return;}
 if(e.target.matches('[data-dismiss]')){A.modal=null;render();return;}
 const button=e.target.closest('[data-action]');if(!button||button.disabled)return;e.preventDefault();try{await handleAction(button);}catch(err){toast(err.message||'Could not complete action',true);console.warn(err);}
});
document.addEventListener('submit',async e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const button=form.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;try{await handleForm(form);}catch(err){toast(err.message,true);}finally{if(button?.isConnected)button.disabled=false;}});
document.addEventListener('input',e=>{
 const el=e.target;if(el.dataset.actionInput==='filter-games'){const term=el.value.toLowerCase().trim();$$('[data-search-title]').forEach(card=>card.hidden=!card.dataset.searchTitle.includes(term));return;}
 if(el.dataset.color){const key=el.dataset.color,base=A.custom||A.themes[localStorage.getItem('gridline:theme')||'papaya'];A.custom={...base,[key]:el.value};localStorage.setItem('gridline:custom',JSON.stringify(A.custom));applyTheme(A.custom);const label=$(`[data-hex="${key}"]`);if(label)label.textContent=el.value.toUpperCase();return;}
 if(!A.draft)return;
 if(el.dataset.gameField){A.draft[el.dataset.gameField]=el.value;dirty();return;}
 if(el.dataset.catName){for(const r of A.draft.rounds){const c=r.categories.find(c=>c.id===el.dataset.catName);if(c){c.name=el.value;dirty();return;}}}
 if(el.dataset.final){const key=el.dataset.final;A.draft.final[key]=key==='timeLimit'?Number(el.value):el.value;dirty();return;}
 if(el.dataset.teamField){const t=A.draft.settings.teams.find(t=>t.id===el.dataset.teamField);if(t){t.name=el.value;dirty();}return;}
 if(el.dataset.qfield&&A.editingQuestion){const q=questionById(A.draft,A.editingQuestion)?.q;if(!q)return;const key=el.dataset.qfield;q[key]=['value','timeLimit'].includes(key)?Number(el.value):el.value;dirty();return;}
});
document.addEventListener('change',async e=>{const el=e.target;try{
 if(el.matches('[data-live-theme]')){await command({type:'setTheme',theme:el.value});return;}
 if(el.dataset.gameSetting&&A.draft){const key=el.dataset.gameSetting;A.draft.settings[key]=el.type==='checkbox'?(key==='buzzerMode'?(el.checked?'auto':'manual'):el.checked):el.type==='number'?Number(el.value):el.value;dirty();if(key==='theme')render();return;}
 }catch(err){toast(err.message,true);}
});
document.addEventListener('keydown',async e=>{
 if(e.key==='Escape'&&A.modal){A.modal=null;render();return;}
 if(!/\/control$/.test(location.pathname)||A.modal||e.ctrlKey||e.metaKey||e.altKey||e.repeat||/^(INPUT|TEXTAREA|SELECT|BUTTON)$/.test(e.target.tagName)||e.target.isContentEditable)return;
 const s=A.session;if(!s)return;let cmd=null;
 if(e.key.toLowerCase()==='t'&&['question','final-question'].includes(s.phase))cmd={type:s.timer.running?'pauseTimer':'startTimer'};
 if(e.key.toLowerCase()==='b'&&s.phase==='question')cmd={type:s.buzzerOpen?'closeBuzz':'openBuzz'};
 if(e.key.toLowerCase()==='a'&&s.phase==='question')cmd={type:'reveal'};
 if(e.key.toLowerCase()==='r'&&s.phase==='question')cmd={type:'complete'};
 if(['c','x'].includes(e.key.toLowerCase())&&s.phase==='question')cmd={type:'judge',correct:e.key.toLowerCase()==='c',teamId:$('#judge-team')?.value||s.teams[0].id};
 if(e.key.toLowerCase()==='f'){e.preventDefault();await handleAction({dataset:{action:'fullscreen'}});return;}
 if(cmd){e.preventDefault();await command(cmd);}
});
window.addEventListener('popstate',loadNavigate);
window.addEventListener('unhandledrejection',e=>{console.error(e.reason);toast(e.reason?.message||'Unexpected connection error',true);});
(async function boot(){try{const [user,themes,templates]=await Promise.all([api('/api/auth/me'),api('/api/themes'),api('/api/templates')]);A.user=user;A.themes=themes;A.templates=templates;try{A.custom=JSON.parse(localStorage.getItem('gridline:custom')||'null');}catch{}if(user)A.prefs=await api('/api/settings');await loadNavigate();}catch(e){console.error(e);$('#app').innerHTML=`<div class="shell pad-y"><div class="eyebrow">SYSTEM INITIALIZATION ERROR</div><h1 class="display h2">GRIDLINE CONNECTION NEEDED.</h1><p>${esc(e.message)}</p><p>Check your internet connection or start the local Cloudflare preview with <code>npm run dev</code>.</p></div>`;}})();
